def get_ui_icon(name, size=15, color="#0F2942"):
    """Returns a crisp single-line inline SVG UI icon without emojis."""
    tpl = UI_ICONS.get(name, UI_ICONS['issue'])
    return tpl.format(size=size, color=color)
